svg.script:
(function(){
  var root = document.currentScript && document.currentScript.ownerSVGElement
    ? document.currentScript.ownerSVGElement
    : (typeof document !== 'undefined' ? document.querySelector('.a6p1-root') : null);
  if(!root) return;

  var Q = function(sel){ return root.querySelector(sel); };
  var phase = 0;
  var playing = false;
  var timers = [];
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e) { reduce = false; }

  var statusEl = Q('#a6p1-status');
  var timerEl = Q('#a6p1-timer-label');
  var liveEl = Q('#a6p1-live');
  var progress = Q('#a6p1-progress');
  var tip = Q('#a6p1-tip');
  var dayTrack = Q('#a6p1-day-track');
  var playBtn = Q('#a6p1-play');
  var resetBtn = Q('#a6p1-reset');

  var phaseCopy = [
    { status: 'Atento · engajado', timer: '0 s · consciência engajada', live: 'Estado atento. Criança engajada com a atividade.', x2: 28 },
    { status: 'Desligar · olhar fixo', timer: '5–20 s · contato interrompido', live: 'Olhar fixo por segundos. Atividade mental interrompida; retomará sem confusão prolongada.', x2: 180 },
    { status: 'Retoma · mesmo ponto', timer: 'fim · volta ao estado prévio', live: 'Retomada ao estado prévio. O episódio foi breve; o dia continua com novos picos.', x2: 332 }
  ];

  function clearTimers(){
    for(var i=0;i<timers.length;i++){ clearTimeout(timers[i]); }
    timers = [];
    playing = false;
    root.setAttribute('data-playing','0');
  }

  function setPhase(p, fromSim){
    phase = p;
    root.setAttribute('data-phase', String(p));
    var c = phaseCopy[p];
    if(statusEl) statusEl.textContent = c.status;
    if(timerEl) timerEl.textContent = c.timer;
    if(liveEl) liveEl.textContent = c.live;
    if(progress) progress.setAttribute('x2', String(c.x2));
    if(!fromSim && p === 1){
      highlightTicks(true);
    }
    if(p === 0){
      highlightTicks(false);
    }
  }

  function highlightTicks(on){
    var ticks = root.querySelectorAll('.a6p1-day-tick');
    for(var i=0;i<ticks.length;i++){
      ticks[i].setAttribute('opacity', on ? (i % 3 === 0 ? '1' : '0.55') : '0.75');
      ticks[i].setAttribute('stroke-width', on && i % 4 === 0 ? '2.4' : '1.6');
    }
  }

  function buildDayTicks(){
    if(!dayTrack) return;
    var xs = [8,18,30,42,55,68,80,92,108,120,135,148,162,175,188,200,214,228,242,255,268,282,295,308,320,332,345,352];
    for(var i=0;i<xs.length;i++){
      var h = (i % 5 === 0) ? 22 : (i % 2 === 0 ? 16 : 12);
      var y = 18 - h/2;
      var line = document.createElementNS('http://www.w3.org/2000/svg','line');
      line.setAttribute('class','a6p1-day-tick');
      line.setAttribute('x1', String(xs[i]));
      line.setAttribute('x2', String(xs[i]));
      line.setAttribute('y1', String(y));
      line.setAttribute('y2', String(y+h));
      line.setAttribute('stroke','var(--a6p1-cyan, #22D3EE)');
      line.setAttribute('stroke-width','1.6');
      line.setAttribute('stroke-linecap','round');
      line.setAttribute('opacity','0.75');
      dayTrack.appendChild(line);
    }
  }

  function simulate(){
    clearTimers();
    playing = true;
    root.setAttribute('data-playing','1');
    setPhase(0, true);
    if(reduce){
      setPhase(1, true);
      highlightTicks(true);
      timers.push(setTimeout(function(){
        setPhase(2, true);
        timers.push(setTimeout(function(){
          setPhase(0, true);
          playing = false;
          root.setAttribute('data-playing','0');
        }, 700));
      }, 900));
      return;
    }
    timers.push(setTimeout(function(){
      setPhase(1, true);
      highlightTicks(true);
    }, 500));
    timers.push(setTimeout(function(){
      setPhase(2, true);
    }, 2200));
    timers.push(setTimeout(function(){
      setPhase(0, true);
      playing = false;
      root.setAttribute('data-playing','0');
    }, 3200));
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p1-tip-t1');
    var t2el = Q('#a6p1-tip-t2');
    var bg = Q('#a6p1-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p1-gold, #FBBF24)');
    var p = clientToSvg(cx, cy);
    var w = 260, h = 56, off = 14;
    var x = p.x + off, y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 540) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')');
    tip.setAttribute('opacity','1');
    tip.setAttribute('aria-hidden','false');
  }

  function hideTip(){
    if(!tip) return;
    tip.setAttribute('opacity','0');
    tip.setAttribute('aria-hidden','true');
  }

  function bindPhase(el){
    if(!el) return;
    el.addEventListener('click', function(){
      clearTimers();
      setPhase(parseInt(el.getAttribute('data-phase'),10) || 0, false);
    });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        clearTimers();
        setPhase(parseInt(el.getAttribute('data-phase'),10) || 0, false);
      }
    });
  }

  bindPhase(Q('#a6p1-phase0'));
  bindPhase(Q('#a6p1-phase1'));
  bindPhase(Q('#a6p1-phase2'));

  if(playBtn){
    playBtn.addEventListener('click', simulate);
    playBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); simulate(); }
    });
  }
  if(resetBtn){
    resetBtn.addEventListener('click', function(){ clearTimers(); setPhase(0,false); });
    resetBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); clearTimers(); setPhase(0,false); }
    });
  }

  var tips = {
    age: ['Idade didática', 'Criança em idade escolar — padrão diário denso.', 'var(--a6p1-indigo, #818CF8)'],
    freq: ['Frequência', 'Dezenas de episódios breves no mesmo dia.', 'var(--a6p1-cyan, #22D3EE)'],
    rit: ['Ritalina falha', 'Psicoestimulante não interrompe o desligar.', 'var(--a6p1-gold, #FBBF24)']
  };

  function bindChip(id, key){
    var el = Q(id);
    if(!el) return;
    var data = tips[key];
    function go(ev){
      var cx = (ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 14;
      showTip(cx, cy, data[0], data[1], data[2]);
      if(liveEl) liveEl.textContent = data[0] + '. ' + data[1];
    }
    el.addEventListener('mouseenter', go);
    el.addEventListener('mousemove', function(ev){ if(tip && tip.getAttribute('opacity')==='1') go(ev); });
    el.addEventListener('mouseleave', hideTip);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      showTip(b.left + b.width/2, b.top + b.height/2, data[0], data[1], data[2]);
    });
    el.addEventListener('blur', hideTip);
    el.addEventListener('click', go);
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); go(ev); }
    });
  }
  bindChip('#a6p1-chip-age','age');
  bindChip('#a6p1-chip-freq','freq');
  bindChip('#a6p1-chip-rit','rit');

  root.addEventListener('click', function(ev){
    var t = ev.target;
    var chips = Q('#a6p1-chips');
    if(chips && chips.contains(t)) return;
    hideTip();
  });

  buildDayTicks();
  setPhase(0, false);
})();
